/**
 * build-ds-bundle.mjs — generate the ds-bundle build artifact.
 *
 * The ds-bundle is the browser runtime + documentation the kernel-studio-server
 * consumes. It is a gitignored build artifact (never tracked): rebuild with
 *   node scripts/build-ds-bundle.mjs
 * from kernel-portal/.
 *
 * Produces under ../ds-bundle/:
 *   _vendor/react.js        vendored React 19 as window.React (IIFE)
 *   _vendor/react-dom.js    vendored ReactDOM 19 as window.ReactDOM (IIFE)
 *   _ds_bundle.js           all UI components as window.Kernel.* (IIFE)  [vite.lib.config.ts]
 *   _ds_bundle.css          component + theme CSS                        [vite.lib.config.ts]
 *   styles.css              base stylesheet (re-exports _ds_bundle.css)
 *   components/general/<Name>/  per-component prompt-guidance.md, declarations.d.ts, harness.jsx
 *   README.md, guidelines/, tokens/  design docs consumed by read-design-docs
 *
 * The loader (kernel-portal/src/studio/loader.ts) injects, in order:
 *   styles.css, _ds_bundle.css, _vendor/react.js, _vendor/react-dom.js, _ds_bundle.js
 * and then reads window.Kernel / window.React / window.ReactDOM.
 */
import { build } from "vite"
import fs from "node:fs/promises"
import path from "node:path"
import { fileURLToPath } from "node:url"

const __dirname = path.dirname(fileURLToPath(import.meta.url))
const portalRoot = path.resolve(__dirname, "..")
const bundleDir = path.resolve(portalRoot, "..", "ds-bundle")
const uiDir = path.resolve(portalRoot, "src/components/ui")

const log = (...a) => console.log("[build-ds-bundle]", ...a)

async function rmrf(p) {
  await fs.rm(p, { recursive: true, force: true })
}

/** Build a tiny IIFE that imports a package and assigns it to a window global. */
async function buildVendor(pkg, globalName, outFile) {
  const tmpEntry = path.resolve(portalRoot, `.vendor-entry-${globalName}.js`)
  await fs.writeFile(
    tmpEntry,
    `import * as mod from "${pkg}"\nwindow.${globalName} = mod.default ?? mod\n`,
    "utf8",
  )
  try {
    await build({
      configFile: false,
      logLevel: "error",
      build: {
        lib: { entry: tmpEntry, name: globalName, formats: ["iife"], fileName: () => path.basename(outFile) },
        outDir: path.dirname(outFile),
        emptyOutDir: false,
        minify: false,
        sourcemap: false,
        rollupOptions:
          globalName === "ReactDOM"
            ? { external: ["react"], output: { globals: { react: "React" } } }
            : {},
      },
    })
  } finally {
    await fs.rm(tmpEntry, { force: true })
  }
}

/**
 * The exact set of names re-exported by src/ds-entry.ts — the authoritative
 * window.Kernel surface. Parsed from the entry rather than the bundled output
 * so it never sweeps in bundled-dependency internals (rolldown hoists all
 * `exports.X =` assignments together, which a naive scan can't separate).
 */
async function entryExports() {
  const src = await fs.readFile(path.resolve(portalRoot, "src/ds-entry.ts"), "utf8")
  const names = new Set()
  const brace = /export\s+\{([^}]+)\}\s+from/g
  let m
  while ((m = brace.exec(src)) !== null) {
    for (const part of m[1].split(",")) {
      const cleaned = part.trim().replace(/^type\s+/, "").split(/\s+as\s+/).pop()?.trim()
      if (cleaned) names.add(cleaned)
    }
  }
  const decl = /export\s+(?:function|const)\s+(\w+)/g
  while ((m = decl.exec(src)) !== null) names.add(m[1])
  // `export * from "./components/ui/icon"` — include every icon symbol.
  if (/export\s+\*\s+from\s+["']\.\/components\/ui\/icon["']/.test(src)) {
    for (const n of await exportsOf("icon")) names.add(n)
  }
  return [...names].sort()
}

/**
 * Build the component bundle (window.Kernel) + CSS via vite.lib.config.ts,
 * then append a canonical entry-export marker the ds-bundle tools parse.
 * Format matches the marker `bundleExports()` in ds-bundle-tools.ts reads:
 *   __export(ds_entry_exports, {\n  Name: () => Impl,\n  ... });
 */
async function buildComponents() {
  await build({ configFile: path.resolve(portalRoot, "vite.lib.config.ts") })
  const names = await entryExports()
  // A parse-only marker in a block comment: never executed, always valid JS.
  // ds-bundle-tools.ts bundleExports() text-searches for this exact block and
  // reads `Name: () => …,` entries until the first `});`.
  const marker =
    `\n/* ds-bundle entry export map (generated by build-ds-bundle.mjs) — parse-only\n` +
    `__export(ds_entry_exports, {\n` +
    names.map((n) => `  ${n}: () => ${n},`).join("\n") +
    `\n});\n*/\n`
  const bundlePath = path.join(bundleDir, "_ds_bundle.js")
  await fs.appendFile(bundlePath, marker, "utf8")
}

async function listComponentFiles() {
  const files = await fs.readdir(uiDir)
  return files.filter((f) => f.endsWith(".tsx")).map((f) => f.replace(/\.tsx$/, ""))
}

/** camel/pascal display name from a kebab file name (button -> Button, alert-dialog -> AlertDialog). */
function pascal(name) {
  return name
    .split("-")
    .map((s) => s.charAt(0).toUpperCase() + s.slice(1))
    .join("")
}

/** Extract the exported symbol names from a component source file. */
async function exportsOf(file) {
  const src = await fs.readFile(path.join(uiDir, `${file}.tsx`), "utf8")
  const names = new Set()
  const brace = /export\s+\{([^}]+)\}/g
  let m
  while ((m = brace.exec(src)) !== null) {
    for (const part of m[1].split(",")) {
      const cleaned = part.trim().replace(/^type\s+/, "").split(/\s+as\s+/).pop()?.trim()
      if (cleaned) names.add(cleaned)
    }
  }
  const decl = /export\s+(?:function|const)\s+(\w+)/g
  while ((m = decl.exec(src)) !== null) names.add(m[1])
  return [...names]
}

async function generateComponentDocs(files) {
  const generalDir = path.join(bundleDir, "components", "general")
  await fs.mkdir(generalDir, { recursive: true })
  for (const file of files) {
    const name = pascal(file)
    const dir = path.join(generalDir, name)
    await fs.mkdir(dir, { recursive: true })
    const names = await exportsOf(file)

    await fs.writeFile(
      path.join(dir, `${name}.prompt.md`),
      `# ${name}\n\n` +
        `Kernel design-system component. Source: \`kernel-portal/src/components/ui/${file}.tsx\`.\n\n` +
        `## Exports on window.Kernel\n\n` +
        names.map((n) => `- \`Kernel.${n}\``).join("\n") +
        `\n\n## Usage\n\n` +
        `Destructure the names you need from \`window.Kernel\`. Style with Kernel CSS custom properties in inline styles ` +
        `(\`--background\`, \`--foreground\`, \`--card\`, \`--border\`, \`--muted\`, \`--status-*\`, \`--brand-*\`).\n`,
      "utf8",
    )

    await fs.writeFile(
      path.join(dir, `${name}.d.ts`),
      `// Type declarations for ${name} (kernel ds-bundle).\n` +
        `// Full source: kernel-portal/src/components/ui/${file}.tsx\n` +
        `import type * as React from "react"\n\n` +
        names
          .map((n) => `export declare const ${n}: React.FC<Record<string, unknown>> & Record<string, unknown>`)
          .join("\n") +
        `\n`,
      "utf8",
    )

    const primary = names[0] ?? name
    await fs.writeFile(
      path.join(dir, `${name}.jsx`),
      `// Minimal harness for ${name}. React and Kernel are browser globals.\n` +
        `export default function Harness() {\n` +
        `  const { ${primary} } = window.Kernel\n` +
        `  return React.createElement(${primary}, null, "${name}")\n` +
        `}\n`,
      "utf8",
    )
  }
  return generalDir
}

async function generateDesignDocs(files) {
  await fs.mkdir(path.join(bundleDir, "guidelines"), { recursive: true })
  await fs.mkdir(path.join(bundleDir, "tokens"), { recursive: true })

  const inventory = files.map((f) => `- ${pascal(f)} (\`${f}.tsx\`)`).join("\n")
  await fs.writeFile(
    path.join(bundleDir, "README.md"),
    `# Kernel ds-bundle\n\n` +
      `Browser runtime + docs for the Kernel design system, consumed by kernel-studio-server.\n` +
      `Built from \`kernel-portal/\` source with \`node scripts/build-ds-bundle.mjs\`. Gitignored build artifact.\n\n` +
      `## Components (${files.length})\n\n${inventory}\n\n` +
      `## Runtime load order\n\n` +
      `styles.css → _ds_bundle.css → _vendor/react.js → _vendor/react-dom.js → _ds_bundle.js\n` +
      `Then window.Kernel / window.React / window.ReactDOM are available.\n`,
    "utf8",
  )

  await fs.writeFile(
    path.join(bundleDir, "guidelines", "composition-guidelines.md"),
    `# Composition guidelines\n\n` +
      `Prototype screens run in the browser with \`window.Kernel\`, \`window.React\`, \`window.ReactDOM\` loaded.\n` +
      `Each screen default-exports \`Screen({ navigate, Kernel })\` and never imports modules.\n\n` +
      `- Style with Kernel CSS custom properties in inline styles.\n` +
      `- Persistent lifecycle state uses \`Kernel.StatusBadge\`; momentary outcomes use \`Kernel.Badge\` / \`Kernel.Alert\`.\n` +
      `- Base UI triggers use \`render={<Kernel.Button>…</Kernel.Button>}\` (DrawerTrigger is the exception).\n` +
      `- Subcomponent names follow shadcn conventions (TabsList/TabsTrigger/TabsContent — no TabsTab/TabsPanel).\n`,
    "utf8",
  )

  await fs.writeFile(
    path.join(bundleDir, "tokens", "token-reference.md"),
    `# Token reference\n\n` +
      `Kernel exposes theme tokens as CSS custom properties (defined in \`_ds_bundle.css\` \`:root\` / \`.dark\`).\n\n` +
      `Common tokens: --background, --foreground, --card, --border, --muted, --muted-foreground,\n` +
      `--primary, --brand-*, --status-* (draft/active/success/warning/danger/neutral),\n` +
      `--font-sans, --font-mono, --radius, --control-h-sm/--control-h/--control-h-lg.\n`,
    "utf8",
  )
}

async function generateBaseStyles() {
  await fs.writeFile(
    path.join(bundleDir, "styles.css"),
    `/* Base stylesheet for the ds-bundle runtime. */\n@import "./_ds_bundle.css";\n`,
    "utf8",
  )
}

async function main() {
  log("cleaning", bundleDir)
  await rmrf(bundleDir)
  await fs.mkdir(path.join(bundleDir, "_vendor"), { recursive: true })

  log("building components (window.Kernel) + CSS")
  await buildComponents()

  log("vendoring React")
  await buildVendor("react", "React", path.join(bundleDir, "_vendor", "react.js"))
  log("vendoring ReactDOM")
  await buildVendor("react-dom/client", "ReactDOM", path.join(bundleDir, "_vendor", "react-dom.js"))

  log("generating base styles")
  await generateBaseStyles()

  const files = await listComponentFiles()
  log(`generating per-component docs for ${files.length} components`)
  await generateComponentDocs(files)

  log("generating design docs")
  await generateDesignDocs(files)

  log("done →", bundleDir)
}

main().catch((err) => {
  console.error("[build-ds-bundle] FAILED:", err)
  process.exit(1)
})
